// Code in JavaScript2 - Bulletproof Price & Payload Preservation

// 1. קבלת הקלט מהאורקסטרטור
const item = $input.item.json;

// 2. פענוח בטוח של הפלט
let parsedData = {};
if (typeof item === 'string') {
    try {
        parsedData = JSON.parse(item);
    } catch (e) {
        parsedData = { output: item };
    }
} else if (item.response && typeof item.response === 'string') {
    try {
        parsedData = JSON.parse(item.response);
    } catch (e) {
        parsedData = item;
    }
} else if (item.output && typeof item.output === 'string') {
    try {
        parsedData = JSON.parse(item.output);
    } catch (e) {
        parsedData = item;
    }
} else {
    parsedData = item;
}

// 3. חילוץ מערך הצינור (Pipeline)
let pipeline = parsedData.pipeline || item.pipeline || [];
if (typeof pipeline === 'string') {
    try {
        pipeline = JSON.parse(pipeline);
    } catch (e) {
        pipeline = [];
    }
}

// 4. חילוץ אובייקט ה-Data וה-Session
let data = parsedData.data || item.data || {};
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        data = {};
    }
}

const sessionId = item.sessionId || parsedData.sessionId || data.sessionId || `SESS-${Date.now()}`;

// בדיקת דילוג פנימית עבור תת-הוורקפלו של הסוכן
let skipped = "";
if (!pipeline.includes("Technical") && !pipeline.includes("Technical_Agent")) {
    skipped = "Technical";
}

// 5. גילוי מק"ט וכמות
let partNumber = parsedData.partNumber || data.partNumber || item.partNumber || "";
if (!partNumber || partNumber === "Electro-Tech" || partNumber === "UNKNOWN") {
    try {
        const prevNode = $("Guardrail_Filter1").item.json;
        if (prevNode && prevNode.partNumber) partNumber = prevNode.partNumber;
    } catch (err) {
        partNumber = "";
    }
}

let quantity = 0;
if (parsedData.quantity !== undefined && parseInt(parsedData.quantity) > 0) {
    quantity = parseInt(parsedData.quantity);
} else if (data.quantity !== undefined && parseInt(data.quantity) > 0) {
    quantity = parseInt(data.quantity);
} else if (item.quantity !== undefined && parseInt(item.quantity) > 0) {
    quantity = parseInt(item.quantity);
}

if (quantity === 0) { 
    try {
        const prevNode = $("Guardrail_Filter1").item.json;
        if (prevNode && prevNode.quantity) quantity = parseInt(prevNode.quantity);
    } catch (err) {
        quantity = 0;
    }
}

// ==============================================
// 6. חילוץ וסריקת חירום של סכום הכסף (totalPriceILS) ו-Quote ID
// ==============================================
let totalPriceILS = Number(data.totalPriceILS || data.totalPriceList || parsedData.totalPriceILS || item.totalPriceILS || 0);
let quoteId = data.quoteId || parsedData.quoteId || item.quoteId || "";

// סריקת טקסט חירום במידה והמחיר או ה-Quote ID חסרים
let rawEmail = "";
try {
    rawEmail = $('Code in JavaScript1').first()?.json?.originalEmail || 
               $('Code in JavaScript1').first()?.json?.emailContent || 
               $('Guardrail_Filter1').first()?.json?.text || "";
} catch (e) {
    rawEmail = "";
}

if (!totalPriceILS && rawEmail) {
    const priceMatch = rawEmail.match(/(?:Total Price|Total|NIS|ILS|₪)\s*:?\s*(?:NIS|ILS|₪)?\s*([\d,.]+)/i);
    if (priceMatch) {
        totalPriceILS = parseFloat(priceMatch[1].replace(/,/g, ''));
    }
}

if (!quoteId && rawEmail) {
    const quoteMatch = rawEmail.match(/Q-2026-\d+/i);
    if (quoteMatch) {
        quoteId = quoteMatch[0];
    }
}

// 7. בניית ה-State המשוטח המלא
const customerId = parsedData.customerId || data.customerId || item.customerId || "";
const customerEmail = parsedData.customerEmail || data.customerEmail || item.customerEmail || "";
const orderType = parsedData.orderType || data.orderType || item.orderType || (rawEmail.match(/datasheet|catalog|specs|RFI|information/i) ? "RFI" : "RFQ");

const state = {
    sessionId: sessionId,
    pipeline: pipeline,
    currentStep: 1,
    totalSteps: pipeline.length || (orderType === "RFI" ? 2 : 4),
    status: "in_progress",
    skipped: skipped,

    partNumber: partNumber,
    quantity: quantity,
    customerId: customerId,
    customerEmail: customerEmail,
    orderType: orderType,
    isDefense: !!(parsedData.isDefense || data.isDefense || item.isDefense),
    isUrgent: !!(parsedData.isUrgent || data.isUrgent || item.isUrgent),

    // הזרקה מפורשת של שדות המחיר וההצעה
    totalPriceILS: totalPriceILS,
    totalPriceList: totalPriceILS,
    customerPriceILS: totalPriceILS,
    quoteId: quoteId,

    data: {
        sessionId: sessionId,
        partNumber: partNumber,
        quantity: quantity,
        customerId: customerId,
        customerEmail: customerEmail,
        totalPriceILS: totalPriceILS,
        totalPriceList: totalPriceILS,
        customerPriceILS: totalPriceILS,
        quoteId: quoteId
    },
    results: parsedData.results || item.results || {}
};

console.log("=== CODE 2 FINAL OUTPUT WITH PRICING & QUOTE ===");
console.log(JSON.stringify(state, null, 2));

return [{ json: state }];

// ==============================================
// 0. חילוץ היסטורי בטוח מנודים קודמים ב-n8n (מניעת איבוד מידע)
// ==============================================
let historicalData = {
    pipeline: [],
    sessionId: "",
    partNumber: "",
    quantity: 0,
    currentStep: 1,
    totalSteps: 4,
    orderType: "RFQ",
    customerId: "",
    customerEmail: "",
    partName: "DC Axial Fan",
    manufacturer: "Sanyo Denki",
    category: "Cooling Fans",
    results: {}
};

// ניסיון משיכת נתונים בטוחה מ-Code2 (או מהאורקסטרטור כגיבוי)
try {
    const prev = $("Code in JavaScript2").item.json;
    if (prev) {
        if (prev.pipeline) historicalData.pipeline = prev.pipeline;
        if (prev.sessionId) historicalData.sessionId = prev.sessionId;
        if (prev.partNumber) historicalData.partNumber = prev.partNumber;
        if (prev.quantity) historicalData.quantity = prev.quantity;
        if (prev.currentStep !== undefined) historicalData.currentStep = prev.currentStep;
        if (prev.totalSteps) historicalData.totalSteps = prev.totalSteps;
        if (prev.orderType) historicalData.orderType = prev.orderType;
        if (prev.customerId) historicalData.customerId = prev.customerId;
        if (prev.customerEmail) historicalData.customerEmail = prev.customerEmail;
        if (prev.partName) historicalData.partName = prev.partName;
        if (prev.manufacturer) historicalData.manufacturer = prev.manufacturer;
        if (prev.category) historicalData.category = prev.category;
        if (prev.results) historicalData.results = prev.results;
    }
} catch (e) {
    try {
        const orch = $("Orchestrator").item.json;
        if (orch) {
            if (orch.pipeline) historicalData.pipeline = orch.pipeline;
            if (orch.sessionId) historicalData.sessionId = orch.sessionId;
            if (orch.partNumber) historicalData.partNumber = orch.partNumber;
            if (orch.quantity) historicalData.quantity = orch.quantity;
            if (orch.orderType) historicalData.orderType = orch.orderType;
            if (orch.customerId) historicalData.customerId = orch.customerId;
            if (orch.customerEmail) historicalData.customerEmail = orch.customerEmail;
        }
    } catch (err) {
        console.log("Could not fetch historical data from prior nodes");
    }
}

// ==============================================
// 0.5. חילוץ בטוח של חוקי העסק (business_rules) עבור סוכן התמחור
// ==============================================
let businessRules = {};
try {
    const initNode = $("Init_Session").item.json;
    if (initNode && initNode.business_rules) {
        businessRules = initNode.business_rules;
    } else if (initNode && initNode.session_payload) {
        const parsedPayload = typeof initNode.session_payload === 'string' ? JSON.parse(initNode.session_payload) : initNode.session_payload;
        if (parsedPayload.business_rules) businessRules = parsedPayload.business_rules;
    }
} catch (e) {}

if (!businessRules || Object.keys(businessRules).length === 0) {
    try {
        const bizNode = $("Get_Business_Rules").item.json;
        if (bizNode) {
            businessRules = bizNode.business_rules || bizNode;
        }
    } catch (e) {
        try {
            const bizNode1 = $("Get_Business_Rules1").item.json;
            if (bizNode1) {
                businessRules = bizNode1.business_rules || bizNode1;
            }
        } catch (err) {
            console.log("Could not fetch business_rules from prior nodes");
        }
    }
}

// ==============================================
// 1. קבלת הנתונים ופירסוס תגובת הסוכן הטכני (לפני בדיקת דילוג)
// ==============================================
const inputData = $json;
let technicalResponse = {};
let rawResponseText = inputData.response || "";

try {
    if (inputData.response) {
        if (typeof inputData.response === 'string') {
            technicalResponse = JSON.parse(inputData.response);
        } else if (typeof inputData.response === 'object') {
            technicalResponse = inputData.response;
        }
    }
} catch (e) {
    console.log("Error parsing technical response in Code 3");
}

// ==============================================
// 1.5. מנגנון זיהוי כשל והתאוששות (ERROR / RECOVERY BYPASS)
// ==============================================
const currentStatus = String(technicalResponse.status || inputData.status || "").toUpperCase();
const currentNextAction = String(technicalResponse.nextAction || inputData.nextAction || "").toUpperCase();

const upstreamFailed = currentStatus === "ERROR" || 
                       currentStatus === "REJECTED" || 
                       currentStatus === "FAILED" || 
                       currentNextAction === "ADMIN_REVIEW";

if (upstreamFailed) {
    console.log("Upstream agent flagged an error/rejection. Initiating workflow bypass to Admin.");

    const safeSessionId = technicalResponse.sessionId || inputData.sessionId || historicalData.sessionId || `SESS-${Date.now()}`;

    return [{
        json: {
            ...historicalData,
            ...inputData,
            ...technicalResponse,
            business_rules: businessRules,
            sessionId: safeSessionId,
            decision: "SKIP",
            nextAction: "ADMIN_REVIEW",
            status: "BYPASSED_DUE_TO_ERROR",
            summary: technicalResponse.technicalSummary || inputData.summary || "Pipeline bypassed due to prior agent error or rejection.",
            results: {
                ...(historicalData.results || {}),
                Technical: {
                    status: currentStatus || "REJECTED",
                    summary: technicalResponse.technicalSummary || rawResponseText || "Technical verification failed or rejected."
                }
            }
        }
    }];
}

// ==============================================
// 2. מנגנון הדילוג הרשמי (RFI / Pricing SKIP)
// ==============================================
const pipeline = ($json.pipeline && $json.pipeline.length > 0) ? $json.pipeline : (technicalResponse.pipeline || historicalData.pipeline || []);
const orderType = String(technicalResponse.orderType || $json.orderType || historicalData.orderType || "").toUpperCase();
const status = String(technicalResponse.status || "").toUpperCase();

const isRFI = ["RFI", "INFORMATION", "REQUEST FOR INFORMATION", "DATASHEET", "CATALOG", "SPECS", "INFO_PROVIDED", "SELECTION_REQUIRED"].includes(orderType) || ["INFO_PROVIDED", "SELECTION_REQUIRED"].includes(status);
const hasPricing = pipeline.includes("Pricing") || pipeline.includes("Pricing_Agent");

if (isRFI || (pipeline.length > 0 && !hasPricing)) {
    console.log("SKIP Code 3 (Pricing): Request is RFI/Info or Pricing not in pipeline - Passing data through unchanged");
    return [{ json: { ...$json, ...technicalResponse, business_rules: businessRules, orderType: isRFI ? "RFI" : orderType } }]; 
}

// ==============================================
// 3. חילוץ מק"ט (ללא הזרקת מק"ט פיקטיבי)
// ==============================================
let partNumber = technicalResponse.partNumber || inputData.partNumber || historicalData.partNumber || "";
if (!partNumber || partNumber === "") {
    const match = rawResponseText.match(/PN:\s*([A-Za-z0-9\-]+)/i);
    if (match) {
        partNumber = match[1];
    }
}
if (!partNumber && inputData.data && inputData.data.partNumber) {
    partNumber = inputData.data.partNumber;
}
if (!partNumber) {
    partNumber = "";
}

// ==============================================
// 4. חילוץ כמות (ללא הזרקת כמות פיקטיבית)
// ==============================================
let quantity = 0;
if (technicalResponse.quantity && technicalResponse.quantity > 0) {
    quantity = parseInt(technicalResponse.quantity);
} else if (inputData.quantity && inputData.quantity > 0) {
    quantity = parseInt(inputData.quantity);
} else if (inputData.data && inputData.data.quantity && inputData.data.quantity > 0) {
    quantity = parseInt(inputData.data.quantity);
} else if (inputData.item && inputData.item.quantity) {
    quantity = parseInt(inputData.item.quantity);
} else if (historicalData.quantity && historicalData.quantity > 0) {
    quantity = historicalData.quantity;
}

// ==============================================
// 5. בניית המצב המשוטח עבור סוכן התמחור
// ==============================================
const safeSessionId = technicalResponse.sessionId || inputData.sessionId || historicalData.sessionId || `SESS-${Date.now()}`;

const updatedState = {
    sessionId: safeSessionId,
    pipeline: pipeline,
    currentStep: (historicalData.currentStep !== undefined) ? Number(historicalData.currentStep) + 1 : 2,
    totalSteps: historicalData.totalSteps || inputData.totalSteps || 4,
    status: "in_progress",

    // הזרקת חוקי העסק המפורשים לסוכן התמחור
    business_rules: businessRules,

    partNumber: partNumber,
    quantity: quantity, 
    partName: technicalResponse.partName || (inputData.data && inputData.data.partName) || historicalData.partName || "DC Axial Fan",
    manufacturer: technicalResponse.manufacturer || (inputData.data && inputData.data.manufacturer) || historicalData.manufacturer || "Sanyo Denki",
    category: technicalResponse.category || (inputData.data && inputData.data.category) || historicalData.category || "Cooling Fans",
    orderType: technicalResponse.orderType || inputData.orderType || historicalData.orderType || "RFQ",
    customerId: inputData.customerId || (inputData.data && inputData.data.customerId) || historicalData.customerId || "",
    customerEmail: inputData.customerEmail || (inputData.data && inputData.data.customerEmail) || historicalData.customerEmail || "",

    data: {
        sessionId: safeSessionId,
        business_rules: businessRules,
        partNumber: partNumber,
        quantity: quantity,
        customerId: inputData.customerId || (inputData.data && inputData.data.customerId) || historicalData.customerId || "",
        customerEmail: inputData.customerEmail || (inputData.data && inputData.data.customerEmail) || historicalData.customerEmail || ""
    },
    results: inputData.results || historicalData.results || {}
};

if (!updatedState.results) { updatedState.results = {}; }
updatedState.results.Technical = {
    status: technicalResponse.status || "APPROVED",
    summary: technicalResponse.technicalSummary || rawResponseText || "Technical verification processed."
};

console.log("========== CODE 3 FINAL OUTPUT ==========");
console.log(JSON.stringify(updatedState, null, 2));

return [{
    json: updatedState
}];

// ==============================================
// Code in JavaScript4 - Strict RFQ/PO OrderType Preservation
// ==============================================
const nodeInput = $json || {};

// 1. שליפת אובייקט הליבה והיסטוריה מנודים קודמים (מניעת איבוד מידע)
let root = {};
try {
  root = $('Code in JavaScript2').first()?.json || $('Orchestrator').first()?.json || {};
} catch (e) {
  root = {};
}

let prevCode3 = {};
try {
  prevCode3 = $('Code in JavaScript3').first()?.json || {};
} catch (e) {
  prevCode3 = {};
}

// 2. חילוץ sessionId מקורי בלבד (ללא מחרוזות קשיחות)
function getValidSessionId(...candidates) {
  for (const cand of candidates) {
    if (cand && typeof cand === 'string' && cand !== 'SESS-UNKNOWN' && cand.trim() !== '') {
      return cand;
    }
  }
  return `SESS-${Date.now()}`;
}

const sessionId = getValidSessionId(
  nodeInput.sessionId,
  prevCode3.sessionId,
  prevCode3.data?.sessionId,
  root.sessionId,
  root.data?.sessionId
);

// 3. חילוץ הרמטי ודינמי של orderType (מניעת הפיכת RFQ ל-PO)
const rawOrderType = nodeInput.orderType || 
                     prevCode3.orderType || 
                     root.orderType || 
                     (root.data && root.data.orderType) || 
                     "RFQ";
const orderType = String(rawOrderType).toUpperCase();

// 4. חילוץ שדות הליבה
const partNumber = nodeInput.partNumber || prevCode3.partNumber || root.partNumber || (root.data && root.data.partNumber) || "";
const quantity = Number(nodeInput.quantity || prevCode3.quantity || root.quantity || (root.data && root.data.quantity) || 0);

// 5. חילוץ סכום התמחור שחושב על ידי Pricing Agent
const totalPriceILS = Number(nodeInput.totalPriceILS || nodeInput.totalPriceList || prevCode3.totalPriceILS || root.totalPriceILS || (root.data && root.data.totalPriceILS) || 0);
const quoteId = nodeInput.quoteId || prevCode3.quoteId || root.quoteId || (root.data && root.data.quoteId) || (orderType === "RFQ" ? `Q-2026-${$execution.id}` : "");

// 6. העברת ה-State עם orderType דינמי ומדויק לסוכן CRM
return [{
  json: {
    ...root,
    ...prevCode3,
    ...nodeInput,
    sessionId: sessionId,
    partNumber: partNumber,
    quantity: quantity,
    totalPriceILS: totalPriceILS,
    totalPriceList: totalPriceILS,
    customerPriceILS: totalPriceILS,
    quoteId: quoteId,
    orderType: orderType, // שימור דינמי מוחלט: RFQ נשאר RFQ, PO נשאר PO
    data: {
      ...(root.data || {}),
      ...(prevCode3.data || {}),
      ...(nodeInput.data || {}),
      sessionId: sessionId,
      partNumber: partNumber,
      quantity: quantity,
      totalPriceILS: totalPriceILS,
      totalPriceList: totalPriceILS,
      customerPriceILS: totalPriceILS,
      quoteId: quoteId,
      orderType: orderType
    }
  }
}];

const inputData = $json || {};

// 1. שליפת נתוני שורש וסוכן CRM
let rootData = {};
try {
  rootData = $('Code in JavaScript2').first()?.json || $('Orchestrator').first()?.json || {};
} catch(e) {
  rootData = {};
}

let crmResponse = {};
try {
  if (inputData.response) {
    crmResponse = typeof inputData.response === 'string' ? JSON.parse(inputData.response) : inputData.response;
  }
} catch (e) {
  crmResponse = {};
}

function getValidSessionId(...candidates) {
  for (const cand of candidates) {
    if (cand && typeof cand === 'string' && cand !== 'SESS-UNKNOWN' && cand.trim() !== '') {
      return cand;
    }
  }
  return `SESS-${Date.now()}`;
}

const sessionId = getValidSessionId(
  inputData.sessionId,
  crmResponse.sessionId,
  rootData.sessionId,
  rootData.data?.sessionId
);

// 2. חילוץ דינמי של orderType (ללא מקבולי hardcoded)
const rawOrderType = inputData.orderType || 
                     crmResponse.orderType || 
                     rootData.orderType || 
                     (rootData.data && rootData.data.orderType) || 
                     "RFQ";
const orderType = String(rawOrderType).toUpperCase();

const partNumber = inputData.partNumber || crmResponse.partNumber || rootData.partNumber || (rootData.data && rootData.data.partNumber) || "";
const quantity = Number(inputData.quantity || crmResponse.quantity || rootData.quantity || (rootData.data && rootData.data.quantity) || 0);
const customerId = inputData.customerId || crmResponse.customerId || rootData.customerId || "";
const customerEmail = inputData.customerEmail || crmResponse.customerEmail || rootData.customerEmail || "";
const quoteId = inputData.quoteId || crmResponse.quoteId || rootData.quoteId || (rootData.data && rootData.data.quoteId) || "";

const customerPriceILS = Number(
  inputData.totalPriceILS || 
  inputData.customerPriceILS || 
  crmResponse.quoteAmountILS || 
  crmResponse.totalPriceILS || 
  rootData.totalPriceILS || 
  (rootData.data && rootData.data.totalPriceILS) || 
  0
);

// 3. בדיקת דילוג עבור RFQ / RFI
const pipeline = inputData.pipeline || rootData.pipeline || [];
const hasProcurement = pipeline.includes("Procurement") || pipeline.includes("Procurement_Agent");
const isRFQorRFI = ["RFQ", "RFI", "INFORMATION", "DATASHEET"].includes(orderType);

if (isRFQorRFI || !hasProcurement) {
  return [{
    json: {
      ...rootData,
      ...inputData,
      sessionId: sessionId,
      partNumber: partNumber,
      quantity: quantity,
      customerId: customerId,
      customerEmail: customerEmail,
      totalPriceILS: customerPriceILS,
      customerPriceILS: customerPriceILS,
      quoteId: quoteId,
      orderType: orderType, // שומר על הערך המקורי (RFQ)
      decision: "SKIP",
      nextAction: "ADMIN",
      summary: `RFQ Stage Completed: Quote ${quoteId} issued by CRM. Procurement skipped.`,
      data: {
        ...(rootData.data || {}),
        ...(inputData.data || {}),
        sessionId: sessionId,
        partNumber: partNumber,
        quantity: quantity,
        customerId: customerId,
        customerEmail: customerEmail,
        totalPriceILS: customerPriceILS,
        quoteId: quoteId,
        orderType: orderType
      }
    }
  }];
}

// 4. נתיב PO בלבד
const totalCostUSD = customerPriceILS > 0 ? Number((customerPriceILS / 3.75 / 1.3).toFixed(2)) : 0;
const unitCostUSD = (quantity > 0 && totalCostUSD > 0) ? Number((totalCostUSD / quantity).toFixed(4)) : 0;
const purchaseOrderId = inputData.purchaseOrderId || inputData.poId || (quoteId ? quoteId.replace(/^Q-/, "PO-") : `PO-2026-${$execution.id}`);

return [{
  json: {
    ...rootData,
    ...inputData,
    sessionId: sessionId,
    partNumber: partNumber,
    quantity: quantity,
    customerId: customerId,
    customerEmail: customerEmail,
    totalPriceILS: customerPriceILS,
    customerPriceILS: customerPriceILS,
    unitCostUSD: unitCostUSD,
    totalCostUSD: totalCostUSD,
    purchaseOrderId: purchaseOrderId,
    poId: purchaseOrderId,
    quoteId: quoteId,
    orderType: "PO",
    data: {
      ...(rootData.data || {}),
      ...(inputData.data || {}),
      sessionId: sessionId,
      partNumber: partNumber,
      quantity: quantity,
      customerId: customerId,
      customerEmail: customerEmail,
      totalPriceILS: customerPriceILS,
      customerPriceILS: customerPriceILS,
      unitCostUSD: unitCostUSD,
      totalCostUSD: totalCostUSD,
      purchaseOrderId: purchaseOrderId,
      poId: purchaseOrderId,
      quoteId: quoteId,
      orderType: "PO"
    }
  }
}];

// ==============================================
// Code in JavaScript6 - Dynamic Session & Full State Pass
// ==============================================

const inputData = $json || {};

// 1. שחזור בטוח מ-Orchestrator ומ-Code 5
let base = {};
try {
  const rawBase = $('Orchestrator').first()?.json?.output || $('Orchestrator').first()?.json || {};
  if (typeof rawBase === 'string') {
    base = JSON.parse(rawBase);
  } else if (typeof rawBase === 'object' && rawBase !== null) {
    base = rawBase;
  }
} catch (e) {
  base = {};
}

let prevCode5 = {};
try {
  prevCode5 = $('Code in JavaScript5').first()?.json || {};
} catch (e) {
  prevCode5 = {};
}

// 2. פענוח פלט סוכן הרכש
let procResp = {};
if (typeof inputData.response === 'string') {
  try {
    procResp = JSON.parse(inputData.response);
  } catch (e) {
    procResp = {};
  }
} else if (typeof inputData.response === 'object' && inputData.response !== null) {
  procResp = inputData.response;
} else {
