else if (inputData.payload && inputData.payload.parts) {
    console.log("Found payload.parts, extracting...");
    for (let part of inputData.payload.parts) {
        if (part.mimeType === 'text/plain' && part.body && part.body.data) {
            try {
                let base64 = part.body.data.replace(/-/g, '+').replace(/_/g, '/');
                emailBody = Buffer.from(base64, 'base64').toString('utf-8');
                console.log("Decoded text/plain part");
                break;
            } catch (e) {
                emailBody = part.body.data;
                console.log("Failed to decode text/plain, used raw");
            }
        }
        // אם מצאנו HTML וטרם מצאנו טקסט
        if (!emailBody && part.mimeType === 'text/html' && part.body && part.body.data) {
            try {
                let base64 = part.body.data.replace(/-/g, '+').replace(/_/g, '/');
                let html = Buffer.from(base64, 'base64').toString('utf-8');
                emailBody = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ');
                console.log("Decoded text/html part");
            } catch (e) {
                // נמשיך הלאה
            }
        }
        // אם יש nested parts
        if (part.parts) {
            for (let subPart of part.parts) {
                if (subPart.mimeType === 'text/plain' && subPart.body && subPart.body.data) {
                    try {
                        let base64 = subPart.body.data.replace(/-/g, '+').replace(/_/g, '/');
                        emailBody = Buffer.from(base64, 'base64').toString('utf-8');
                        console.log("Decoded nested text/plain part");
                        break;
                    } catch (e) {
                        // נמשיך הלאה
                    }
                }
            }
        }
    }
}
// 4. אם יש snippet
else if (inputData.snippet) {
    emailBody = inputData.snippet;
    console.log("Using snippet");
}
// 5. אם יש text
else if (inputData.text) {
    emailBody = inputData.text;
