// ==============================================
let custMatch = emailBody.match(/Customer\s*:\s*([A-Za-z0-9\s\-]+)/i) ||
                emailBody.match(/Customer ID\s*:\s*([A-Za-z0-9\s\-]+)/i);

if (custMatch && custMatch[1]) {
    let raw = cleanText(custMatch[1]);
