// ==============================================
let emailMatch = emailBody.match(/Email[:\s]+([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/i);
if (emailMatch && emailMatch[1]) {
    customerEmail = emailMatch[1];
} else {
    let fromStr = typeof from === 'string' ? from : JSON.stringify(from);
    let fromEmail = fromStr.match(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/);
    if (fromEmail && fromEmail[1]) {
        customerEmail = fromEmail[1];
