// ==============================================
if (emailBody.match(/\bPurchase Order\b|\bPO\b/i) || emailBody.match(/accept the quotation|issue our official purchase order/i)) {
    orderType = "PO";
} else if (emailBody.match(/Quote Request|\bRFQ\b|request for quote|price request|pricing|quotation/i)) {
    orderType = "RFQ";
} else if (emailBody.match(/datasheet|catalog|specs|specification|recommendation|lowest noise|power consumption|RFI|information/i)) {
    orderType = "RFI";
} else {
    orderType = "RFQ"; // ברירת מחדל
}
