// ==============================================
// חילוץ SUPPLIER
// ==============================================
let suppMatch = emailBody.match(/Supplier[:\s]+([A-Za-z0-9\s\-]+)/i);
if (suppMatch && suppMatch[1]) {
    supplier = cleanText(suppMatch[1]);
    if (supplier.match(/sanyo/i)) {
