    orderType: orderType,
    customerApprovedQuote: customerApprovedQuote,
    supplier: supplier,
    supplierId: supplierId,
    currentInventory: currentInventory,
    subject: subject,
    from: from,
    originalEmail: emailBody.substring(0, 2000)
};

console.log("========== FINAL OUTPUT ==========");
console.log(JSON.stringify(output, null, 2));

return [{
    json: output
}];

